import type { ProductRow } from '@/lib/vendor-supabase/types'; type SpecForm = { product_id: string; spec_title: string; spec_text: string; spec_file_url: string;
}; const emptySpec: SpecForm = { product_id: '', spec_title: '', spec_text: '', spec_file_url: '' }; function CatalogWorkspace() { const { feedback, showSuccess, showError } = useVendorFeedback(); const [stockMap, setStockMap] = useState<Record<string, boolean>>(() => Object.fromEntries(MOCK_CATALOG.map((p) => [p.id, p.stockAvailable > 0])), ); const [products, setProducts] = useState<ProductRow[]>([]); const [specOpen, setSpecOpen] = useState(false); const [specForm, setSpecForm] = useState<SpecForm>(emptySpec); const [isSubmitting, setIsSubmitting] = useState(false); const loadProducts = useCallback(async () => { const { data } = await supabase .from('products') .select('id, sku, name') .eq('vendor_id', DEFAULT_VENDOR_ID) .order('name'); if (data) setProducts((data as ProductRow[]) ?? []); }, []); useEffect(() => { void loadProducts(); }, [loadProducts]); const openSpecModal = () => { setSpecForm({ ...emptySpec, product_id: products[0]?.id ?? '', }); setSpecOpen(true); }; const handleSpecSubmit = async (e: React.FormEvent) => { e.preventDefault(); if (!specForm.product_id) { window.alert('Select a product ID.'); return; } setIsSubmitting(true); const { error } = await supabase .from('products') .update({ spec_title: specForm.spec_title.trim(), spec_text: specForm.spec_text.trim(), spec_file_url: specForm.spec_file_url.trim() || null, }) .eq('id', specForm.product_id).eq('vendor_id', DEFAULT_VENDOR_ID); setIsSubmitting(false); if (error) { showError(error.message); window.alert(`Error: ${error.message}`); return; } showSuccess('Spec sheet saved to product catalog.'); setSpecOpen(false); }; return ( <div className="space-y-6"> <VendorModuleHeader title="Product Catalog" description="Medicines, equipment, surgical, and lab SKUs with specs, certifications, and tiered pricing." actions={ <button type="button" onClick={openSpecModal} className="rounded-xl bg-vendor-secondary px-4 py-2 text-xs font-bold text-white hover:opacity-90"> New spec sheet </button> } /> <VendorFeedbackBanner feedback={feedback} /> <VendorDataTable<CatalogProduct> rows={MOCK_CATALOG} rowKey={(p) => p.id} columns={[ { key: 'sku', header: 'SKU', render: (p) => <span className="font-mono font-bold">{p.sku}</span> }, { key: 'name', header: 'Product', render: (p) => p.name }, { key: 'cat', header: 'Category', render: (p) => p.category }, { key: 'price', header: 'Tier pricing', render: (p) => ( <ul className="text-xs"> {p.tierPricing.map((t) => ( <li key={t.tier}> {t.tier}: ₹{t.price} </li> ))} </ul> ), }, { key: 'certs', header: 'Certifications', render: (p) => ( <div className="flex flex-wrap gap-1"> {p.certifications.map((c) => ( <VendorStatusPill key={c} label={c} tone="success" /> ))} </div> ), }, { key: 'stock', header: 'Available', render: (p) => ( <button type="button" onClick={() => setStockMap((m) => ({ ...m, [p.id]: !m[p.id] }))} className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${stockMap[p.id] ? 'bg-emerald-500/15 text-emerald-800' : 'bg-slate-200 text-vendor-muted'}`} > {stockMap[p.id] ? 'In stock' : 'Unavailable'} </button> ), }, ]} /> <VendorModal title="New spec sheet" open={specOpen} onClose={() => setSpecOpen(false)} footer={ <> <button type="button" onClick={() => setSpecOpen(false)} className="rounded-lg border px-4 py-2 text-sm font-bold"> Cancel </button> <button type="submit" form="spec-sheet-form" disabled={isSubmitting} className="rounded-lg bg-vendor-secondary px-4 py-2 text-sm font-bold text-white disabled:opacity-60" > {isSubmitting ? 'Saving…' : 'Save spec sheet'} </button> </> } > <form id="spec-sheet-form" onSubmit={(e) => void handleSpecSubmit(e)} className="space-y-3"> <label className={vendorLabelClass}> Product ID <select required value={specForm.product_id} onChange={(e) => setSpecForm((f) => ({ ...f, product_id: e.target.value }))} className={vendorFieldClass} > <option value="">Select product…</option> {products.map((p) => ( <option key={p.id} value={p.id}> {p.sku} · {p.name} </option> ))} </select> </label> <label className={vendorLabelClass}> Specification title <input required value={specForm.spec_title} onChange={(e) => setSpecForm((f) => ({ ...f, spec_title: e.target.value }))} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> Spec text <textarea required rows={4} value={specForm.spec_text} onChange={(e) => setSpecForm((f) => ({ ...f, spec_text: e.target.value }))} className={vendorFieldClass} /> </label> <label className={vendorLabelClass}> File link (optional) <input type="url" value={specForm.spec_file_url} onChange={(e) => setSpecForm((f) => ({ ...f, spec_file_url: e.target.value }))} placeholder="https://…" className={vendorFieldClass} /> </label> </form> </VendorModal> </div> );
}

export default CatalogWorkspace;
export { CatalogWorkspace };
